export function profileName(value) {
  return String(value).trim();
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { profileName } from '../src/profile.ts';
test('rejects blank names and preserves valid names', () => { assert.throws(() => profileName('  '), /profile name/i); assert.equal(profileName(' Ada '), 'Ada'); });

export const retryDelay = (attempt) => attempt * 100;
export const delayForRetry = retryDelay;
export function nextDelay(attempt) { return retryDelay(attempt); }

import assert from 'node:assert/strict';
import test from 'node:test';
import { delayForRetry, nextDelay } from '../src/retry.mjs';
test('keeps compatibility alias and caller behavior', () => { assert.equal(delayForRetry(2), 200); assert.equal(nextDelay(3), 300); });

export function parseConfig(input = {}) {
  return { maxAttempts: input.maxAttempts ?? 3 };
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { parseConfig } from '../src/config.mjs';
test('parses maxAttempts', () => { assert.equal(parseConfig({}).maxAttempts, 3); assert.equal(parseConfig({ maxAttempts: 10 }).maxAttempts, 10); assert.throws(() => parseConfig({ maxAttempts: 0 }), { message: 'maxAttempts must be an integer from 1 to 10' }); });

export function scheduleRetry(clock, done) {
  const timer = clock.setTimeout(() => done('retry'), 100);
  return { cancel() { done('cancelled'); }, timer };
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { scheduleRetry } from '../src/scheduler.mjs';
test('cancel clears timer and resolves once', () => { let callback; let cleared = false; const values = []; const clock = { setTimeout(fn) { callback = fn; return 7; }, clearTimeout(id) { cleared = id === 7; } }; const job = scheduleRetry(clock, (v) => values.push(v)); job.cancel(); callback(); assert.equal(cleared, true); assert.deepEqual(values, ['cancelled']); });

export const statuses = ['ready', 'failed'];
export function formatStatus(status) { return status === 'ready' ? 'Ready' : 'Failed'; }
export function serializeStatus(status) { return { status }; }

import assert from 'node:assert/strict';
import test from 'node:test';
import { statuses, formatStatus, serializeStatus } from '../src/status.mjs';
test('handles degraded exhaustively', () => { assert.ok(statuses.includes('degraded')); assert.equal(formatStatus('degraded'), 'Degraded'); assert.deepEqual(serializeStatus('degraded'), { status: 'degraded' }); assert.equal(formatStatus('ready'), 'Ready'); });

export function chunk(values, size) {
  const output = [];
  for (let i = 0; i < values.length - size; i += size) output.push(values.slice(i, i + size));
  return output;
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { chunk } from '../src/chunk.mjs';
test('covers exact and remainder boundaries', () => { assert.deepEqual(chunk([1,2], 2), [[1,2]]); assert.deepEqual(chunk([1,2,3], 2), [[1,2],[3]]); assert.deepEqual(chunk([], 2), []); });

export function completion(onComplete) {
  return { fail(error) { onComplete({ ok: false, error }); } };
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { completion } from '../src/completion.mjs';
test('emits once across simultaneous failures', () => { for (let i=0;i<100;i++) { const values=[]; const c=completion((v)=>values.push(v)); c.fail('a'); c.fail('b'); assert.equal(values.length,1); } });

import assert from 'node:assert/strict';
import test from 'node:test';
import { run } from '../src/runner.mjs';
test('uses shell-free argv', () => { const child=run(process.execPath, 'C:\\fixture path\\a;&.mjs', ()=>{}); assert.equal(child.spawnargs.includes('C:\\fixture path\\a;&.mjs'), true); assert.equal(child.spawnargs.some((v)=>v.includes('cmd.exe')), false); child.kill(); });

import assert from 'node:assert/strict';
import test from 'node:test';
import { currentSchemaVersion } from '../src/schema.mjs';
import { consume } from '../src/consumer.mjs';
test('consumer uses the current schema', () => { assert.deepEqual(consume({ id: 'x', state: 'ready' }), { id: 'x', state: 'ready', schemaVersion: currentSchemaVersion }); });

import assert from 'node:assert/strict';
import test from 'node:test';
import { request } from '../src/request.mjs';
import { adapt, logEvent } from '../src/adapter.mjs';
test('propagates requestId end to end', () => { const value=request({ requestId:'r-7', body:'x' }); assert.equal(logEvent(adapt(value)).requestId, 'r-7'); });

import assert from 'node:assert/strict';
import test from 'node:test';
import { clamp } from '../src/math.mjs';
test('clamps inside and outside range', () => { assert.equal(clamp(5, 0, 10), 5); assert.equal(clamp(-1, 0, 10), 0); assert.equal(clamp(11, 0, 10), 10); });

import assert from 'node:assert/strict';
import test from 'node:test';
import { clamp } from '../src/math.mjs';
test('preserves all clamp boundaries', () => { assert.equal(clamp(0,0,10),0); assert.equal(clamp(10,0,10),10); assert.equal(clamp(4,0,10),4); });

import assert from 'node:assert/strict';
import test from 'node:test';
import { profileName } from '../src/profile.mjs';
test('rejects blanks after conflict recovery', () => { assert.throws(() => profileName('\t')); assert.equal(profileName(' Ada '), 'Ada'); });

import assert from 'node:assert/strict';
import test from 'node:test';
import { boundedInteger } from '../src/integer.mjs';
test('rejects partial and non-integer parses', () => { assert.equal(boundedInteger('3',1,5),3); assert.throws(() => boundedInteger('3x',1,5), /integer/); assert.throws(() => boundedInteger('2.5',1,5), /integer/); });
